edits.replacement:
/* v16.xx, seen on the 4K PARTY screenshot (2026-10-08): in a window about 830 menu pixels tall (1080p, 1440p, a 4K window) the
   frame's top line ran 33 pixels down, under the CREDITS readout in the corner. The frame now stays 75 pixels clear of the top
   and bottom, which holds the party content with room and keeps the corner readout off its line. */
#partymodal::before{ inset:50% auto auto 50%; width:min(1180px,calc(100% - 28px)); height:min(760px,calc(100% - 150px)); transform:translate(-50%,-50%); }

check:
{v:'VER',what:'the PARTY frame stays clear of the corner readout: in a window about 830 menu pixels tall its top line sits at least 60 pixels down, below CREDITS',
 run:function(){
   var pm=document.getElementById('partymodal'), bad=[], on0, h0, b0, fh, top;
   if(!pm) return 'SKIP: no PARTY window here';
   on0=pm.classList.contains('on'); h0=pm.style.height; b0=pm.style.bottom;
   try{
     pm.classList.add('on'); pm.style.bottom='auto'; pm.style.height='831px';
     fh=parseFloat(getComputedStyle(pm,'::before').height);
     if(!(fh>0)) return 'SKIP: the frame did not lay out';
     top=(pm.offsetHeight-fh)/2;
     if(!(top>=60)) bad.push('in an 831 pixel window the PARTY frame top is '+Math.round(top)+' pixels down, under the readout');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ pm.style.height=h0; pm.style.bottom=b0; pm.classList.toggle('on',on0); }
   return bad.length?bad.join('; '):null; }},
